/**
 * Tokenizer module for converting various input types to standardized string tokens.
 *
 * This module demonstrates Scala's powerful type system with:
 * - Sealed traits and case classes for algebraic data types
 * - Type classes and implicit conversions
 * - Option/Either for error handling
 * - Immutable collections and functional programming patterns
 */

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import scala.collection.mutable
import scala.util.{Try, Success, Failure}

// ============================================================================
// Enums and Constants
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object String extends TokenType { val value = "string" }
  case object Numeric extends TokenType { val value = "numeric" }
  case object Temporal extends TokenType { val value = "temporal" }
  case object Structured extends TokenType { val value = "structured" }
  case object Binary extends TokenType { val value = "binary" }
  case object Null extends TokenType { val value = "null" }
}

// ============================================================================
// Core Token Classes
// ============================================================================

/**
 * Immutable token representation.
 * Using case class provides equals, hashCode, copy, and pattern matching.
 */
final case class Token(
  value: String,
  tokenType: TokenType,
  metadata: Map[String, Any] = Map.empty
) {
  /** Return new token with additional metadata. */
  def withMetadata(entries: (String, Any)*): Token =
    copy(metadata = metadata ++ entries.toMap)
}

/**
 * Mutable batch of tokens - contrast with immutable Token.
 * Using private[this] for encapsulation.
 */
final class MutableTokenBatch {
  private val _tokens: mutable.ListBuffer[Token] = mutable.ListBuffer.empty
  private var _processed: Boolean = false

  def tokens: List[Token] = _tokens.toList

  def add(token: Token): Unit = {
    if (_processed) throw new RuntimeException("Batch already processed")
    _tokens += token
  }

  def markProcessed(): Unit = _processed = true

  def isProcessed: Boolean = _processed
}

// ============================================================================
// Type Class for Tokenizable (structural typing equivalent)
// ============================================================================

/**
 * Type class for objects that can be converted to a token string.
 * This replaces Python's Protocol with Scala's type class pattern.
 */
trait Tokenizable[A] {
  def toToken(a: A): String
}

object Tokenizable {
  def apply[A](implicit ev: Tokenizable[A]): Tokenizable[A] = ev

  /** Syntax extension for convenient method call syntax */
  implicit class TokenizableOps[A](private val a: A) extends AnyVal {
    def toToken(implicit ev: Tokenizable[A]): String = ev.toToken(a)
  }
}

// ============================================================================
// Generic Container Classes
// ============================================================================

/**
 * Covariant container - can return subtypes.
 * Using +T for covariance in Scala.
 */
final class TokenContainer[+T](items: Seq[T]) {
  private val _items: Vector[T] = items.toVector

  def getAll: Vector[T] = _items

  def mapTokens[U](f: T => String): List[String] =
    _items.map(f).toList
}

/**
 * Contravariant sink - can accept supertypes.
 * Using -T for contravariance in Scala.
 */
final class TokenSink[-T] {
  private val _received: mutable.ListBuffer[Any] = mutable.ListBuffer.empty

  def receive(item: T): Unit = _received += item

  def drain(): List[Any] = {
    val result = _received.toList
    _received.clear()
    result
  }
}

/**
 * Invariant handler - exact type matching required.
 */
final class BivariantHandler[T](private var _value: T) {
  def get: T = _value

  def set(value: T): Unit = _value = value

  def transform(f: T => T): T = {
    _value = f(_value)
    _value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

/**
 * Abstract base tokenizer with generic input type.
 * Using trait with type parameter for abstraction.
 */
trait BaseTokenizer[T] {
  /** Convert value to token. */
  def tokenize(value: T): Token

  /** Lazy tokenization of multiple values using Iterator. */
  def tokenizeBatch(values: Iterable[T]): Iterator[Token] =
    values.iterator.map(tokenize)
}

/**
 * Tokenizer for string and bytes types.
 * In Scala, we use Array[Byte] for bytes.
 */
final class StringTokenizer(
  encoding: String = "UTF-8",
  normalizer: String => String = identity
) extends BaseTokenizer[Either[String, Array[Byte]]] {

  override def tokenize(value: Either[String, Array[Byte]]): Token = {
    val strValue = value match {
      case Left(s)      => s
      case Right(bytes) => new String(bytes, encoding)
    }
    val normalized = normalizer(strValue)
    Token(normalized, TokenType.String)
  }

  /** Convenience method for tokenizing strings directly */
  def tokenizeString(value: String): Token =
    tokenize(Left(value))

  /** Convenience method for tokenizing bytes directly */
  def tokenizeBytes(value: Array[Byte]): Token =
    tokenize(Right(value))
}

/**
 * Numeric value wrapper for type-safe numeric tokenization.
 */
sealed trait NumericValue {
  def originalTypeName: String
}

object NumericValue {
  final case class IntValue(value: Int) extends NumericValue {
    val originalTypeName = "int"
  }
  final case class LongValue(value: Long) extends NumericValue {
    val originalTypeName = "long"
  }
  final case class FloatValue(value: Float) extends NumericValue {
    val originalTypeName = "float"
  }
  final case class DoubleValue(value: Double) extends NumericValue {
    val originalTypeName = "double"
  }
  final case class BigDecimalValue(value: BigDecimal) extends NumericValue {
    val originalTypeName = "BigDecimal"
  }

  implicit def fromInt(i: Int): NumericValue = IntValue(i)
  implicit def fromLong(l: Long): NumericValue = LongValue(l)
  implicit def fromFloat(f: Float): NumericValue = FloatValue(f)
  implicit def fromDouble(d: Double): NumericValue = DoubleValue(d)
  implicit def fromBigDecimal(bd: BigDecimal): NumericValue = BigDecimalValue(bd)
}

/**
 * Tokenizer for numeric types with precision handling.
 * Using immutable Map instead of mutable default argument.
 */
final class NumericTokenizer(
  precision: Int = 6,
  formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[NumericValue] {

  override def tokenize(value: NumericValue): Token = {
    val strValue = value match {
      case NumericValue.IntValue(v)        => v.toString
      case NumericValue.LongValue(v)       => v.toString
      case NumericValue.FloatValue(v)      => s"%.${precision}f".format(v)
      case NumericValue.DoubleValue(v)     => s"%.${precision}f".format(v)
      case NumericValue.BigDecimalValue(v) => v.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString()
    }
    Token(strValue, TokenType.Numeric, Map("original_type" -> value.originalTypeName))
  }

  /** Convenience methods for direct numeric types */
  def tokenizeInt(value: Int): Token = tokenize(NumericValue.IntValue(value))
  def tokenizeLong(value: Long): Token = tokenize(NumericValue.LongValue(value))
  def tokenizeFloat(value: Float): Token = tokenize(NumericValue.FloatValue(value))
  def tokenizeDouble(value: Double): Token = tokenize(NumericValue.DoubleValue(value))
  def tokenizeBigDecimal(value: BigDecimal): Token = tokenize(NumericValue.BigDecimalValue(value))
}

/**
 * Temporal value wrapper for date/time types.
 */
sealed trait TemporalValue

object TemporalValue {
  final case class DateTime(value: LocalDateTime) extends TemporalValue
  final case class Date(value: LocalDate) extends TemporalValue

  implicit def fromLocalDateTime(ldt: LocalDateTime): TemporalValue = DateTime(ldt)
  implicit def fromLocalDate(ld: LocalDate): TemporalValue = Date(ld)
}

/**
 * Tokenizer for date/time types.
 */
final class TemporalTokenizer(formatStr: Option[String] = None) extends BaseTokenizer[TemporalValue] {

  private val IsoFormat: DateTimeFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val DateFormat: DateTimeFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  override def tokenize(value: TemporalValue): Token = {
    val formatted = formatStr match {
      case Some(fmt) =>
        val formatter = DateTimeFormatter.ofPattern(fmt)
        value match {
          case TemporalValue.DateTime(dt) => dt.format(formatter)
          case TemporalValue.Date(d)      => d.format(formatter)
        }
      case None =>
        value match {
          case TemporalValue.DateTime(dt) => dt.format(IsoFormat)
          case TemporalValue.Date(d)      => d.format(DateFormat)
        }
    }
    Token(formatted, TokenType.Temporal)
  }

  /** Convenience methods for direct temporal types */
  def tokenizeDateTime(value: LocalDateTime): Token = tokenize(TemporalValue.DateTime(value))
  def tokenizeDate(value: LocalDate): Token = tokenize(TemporalValue.Date(value))
