/**
 * Functor for tokens.
 * Scala can express true higher-kinded types using F[_] syntax.
 */
final class TokenFunctor[T](private val value: T) {
  def map[U](f: T => U): TokenFunctor[U] =
    new TokenFunctor(f(value))

  def flatMap[U](f: T => TokenFunctor[U]): TokenFunctor[U] =
    f(value)

  def getOrElse(default: => T): T =
    if (value != null) value else default

  def get: T = value
}

object TokenFunctor {
  def apply[T](value: T): TokenFunctor[T] = new TokenFunctor(value)
}

/**
 * Extended monad operations.
