  implicit def fromDouble(d: Double): NumericValue = DoubleValue(d)
  implicit def fromBigDecimal(bd: BigDecimal): NumericValue = BigDecimalValue(bd)
}

/**
 * Tokenizer for numeric types with precision handling.
 * Using immutable Map instead of mutable default argument.
 */
final class NumericTokenizer(
  precision: Int = 6,
  formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[NumericValue] {

  override def tokenize(value: NumericValue): Token = {
    val strValue = value match {
      case NumericValue.IntValue(v)        => v.toString
      case NumericValue.LongValue(v)       => v.toString
      case NumericValue.FloatValue(v)      => s"%.${precision}f".format(v)
      case NumericValue.DoubleValue(v)     => s"%.${precision}f".format(v)
      case NumericValue.BigDecimalValue(v) => v.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString()
    }
    Token(strValue, TokenType.Numeric, Map("original_type" -> value.originalTypeName))
  }

  /** Convenience methods for direct numeric types */
  def tokenizeInt(value: Int): Token = tokenize(NumericValue.IntValue(value))
  def tokenizeLong(value: Long): Token = tokenize(NumericValue.LongValue(value))
  def tokenizeFloat(value: Float): Token = tokenize(NumericValue.FloatValue(value))
  def tokenizeDouble(value: Double): Token = tokenize(NumericValue.DoubleValue(value))
  def tokenizeBigDecimal(value: BigDecimal): Token = tokenize(NumericValue.BigDecimalValue(value))
}

/**
 * Temporal value wrapper for date/time types.
 */
sealed trait TemporalValue

object TemporalValue {
  final case class DateTime(value: LocalDateTime) extends TemporalValue
  final case class Date(value: LocalDate) extends TemporalValue

  implicit def fromLocalDateTime(ldt: LocalDateTime): TemporalValue = DateTime(ldt)
  implicit def fromLocalDate(ld: LocalDate): TemporalValue = Date(ld)
}

/**
 * Tokenizer for date/time types.
 */
final class TemporalTokenizer(formatStr: Option[String] = None) extends BaseTokenizer[TemporalValue] {

  private val IsoFormat: DateTimeFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val DateFormat: DateTimeFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  override def tokenize(value: TemporalValue): Token = {
    val formatted = formatStr match {
      case Some(fmt) =>
        val formatter = DateTimeFormatter.ofPattern(fmt)
        value match {
          case TemporalValue.DateTime(dt) => dt.format(formatter)
          case TemporalValue.Date(d)      => d.format(formatter)
        }
      case None =>
        value match {
          case TemporalValue.DateTime(dt) => dt.format(IsoFormat)
          case TemporalValue.Date(d)      => d.format(DateFormat)
        }
    }
    Token(formatted, TokenType.Temporal)
  }

  /** Convenience methods for direct temporal types */
  def tokenizeDateTime(value: LocalDateTime): Token = tokenize(TemporalValue.DateTime(value))
  def tokenizeDate(value: LocalDate): Token = tokenize(TemporalValue.Date(value))
}

// ============================================================================
// Advanced: Union Types via ADT
// ============================================================================

/**
 * Universal value ADT representing all tokenizable types.
 * Scala uses sealed traits/ADTs instead of Union types.
 */
sealed trait UniversalValue

object UniversalValue {
  case object NullValue extends UniversalValue
  final case class StringValue(value: String) extends UniversalValue
  final case class BytesValue(value: Array[Byte]) extends UniversalValue
  final case class IntValue(value: Int) extends UniversalValue
  final case class LongValue(value: Long) extends UniversalValue
  final case class FloatValue(value: Float) extends UniversalValue
  final case class DoubleValue(value: Double) extends UniversalValue
  final case class BigDecimalValue(value: BigDecimal) extends UniversalValue
  final case class DateTimeValue(value: LocalDateTime) extends UniversalValue
  final case class DateValue(value: LocalDate) extends UniversalValue
  /** Wrapper for any type with a Tokenizable instance */
  final case class TokenizableValue[A](value: A, tokenizer: Tokenizable[A]) extends UniversalValue
  final case class AnyValue(value: Any) extends UniversalValue

  /** Factory method to create TokenizableValue with implicit evidence */
  def tokenizable[A](value: A)(implicit ev: Tokenizable[A]): TokenizableValue[A] =
    TokenizableValue(value, ev)
}

/**
 * Tokenizer that handles multiple types via pattern matching on ADT.
 */
final class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  def tokenize(value: UniversalValue): Token = value match {
    case UniversalValue.NullValue =>
      Token("NULL", TokenType.Null)

    case UniversalValue.StringValue(s) =>
      stringTokenizer.tokenizeString(s)

    case UniversalValue.BytesValue(b) =>
      stringTokenizer.tokenizeBytes(b)

    case UniversalValue.IntValue(i) =>
      numericTokenizer.tokenizeInt(i)

    case UniversalValue.LongValue(l) =>
      numericTokenizer.tokenizeLong(l)

    case UniversalValue.FloatValue(f) =>
      numericTokenizer.tokenizeFloat(f)

    case UniversalValue.DoubleValue(d) =>
      numericTokenizer.tokenizeDouble(d)

    case UniversalValue.BigDecimalValue(bd) =>
      numericTokenizer.tokenizeBigDecimal(bd)

    case UniversalValue.DateTimeValue(dt) =>
      temporalTokenizer.tokenizeDateTime(dt)

    case UniversalValue.DateValue(d) =>
      temporalTokenizer.tokenizeDate(d)

    case UniversalValue.TokenizableValue(t)(ev) =>
      Token(ev.toToken(t), TokenType.Structured)

    case UniversalValue.AnyValue(a) =>
      Token(a.toString, TokenType.String, Map("fallback" -> true))
  }

  /** Convenience method to tokenize any value by wrapping it */
  def tokenizeAny(value: Any): Token = value match {
    case null           => tokenize(UniversalValue.NullValue)
    case s: String      => tokenize(UniversalValue.StringValue(s))
    case b: Array[Byte] => tokenize(UniversalValue.BytesValue(b))
    case i: Int         => tokenize(UniversalValue.IntValue(i))
    case l: Long        => tokenize(UniversalValue.LongValue(l))
    case f: Float       => tokenize(UniversalValue.FloatValue(f))
    case d: Double      => tokenize(UniversalValue.DoubleValue(d))
    case bd: BigDecimal => tokenize(UniversalValue.BigDecimalValue(bd))
    case dt: LocalDateTime => tokenize(UniversalValue.DateTimeValue(dt))
    case d: LocalDate   => tokenize(UniversalValue.DateValue(d))
    case other          => tokenize(UniversalValue.AnyValue(other))
  }
}

// ============================================================================
// Complex Nested Generics
// ============================================================================

/**
 * Registry with complex nested generic types.
 * Using mutable maps internally but exposing immutable views.
 */
final class TokenRegistry[T] {
  private val registry: mutable.Map[String, TokenContainer[T]] = mutable.Map.empty
  private val handlers: mutable.ListBuffer[T => Option[Token]] = mutable.ListBuffer.empty

  def register(key: String, container: TokenContainer[T]): Unit =
    registry(key) = container

  def addHandler(handler: T => Option[Token]): Unit =
    handlers += handler

  def process(key: String): List[Option[Token]] = {
    registry.get(key) match {
      case None => List.empty
      case Some(container) =>
        container.getAll.map { item =>
          handlers.iterator
            .map(h => h(item))
            .find(_.isDefined)
            .flatten
        }.toList
    }
  }
}

// ============================================================================
// Functor/Monad Type Classes (Higher-Kinded Types)
// ============================================================================

/**
 * Functor for tokens.
 * Scala can express true higher-kinded types using F[_] syntax.
 */
final class TokenFunctor[T](private val value: T) {
  def map[U](f: T => U): TokenFunctor[U] =
    new TokenFunctor(f(value))

  def flatMap[U](f: T => TokenFunctor[U]): TokenFunctor[U] =
    f(value)

  def getOrElse(default: => T): T =
    if (value != null) value else default

  def get: T = value
}

object TokenFunctor {
  def apply[T](value: T): TokenFunctor[T] = new TokenFunctor(value)
}

/**
 * Extended monad operations.
 */
final class TokenMonad[T](value: T) extends TokenFunctor[T](value) {
  def ap[U](funcWrapped: TokenMonad[T => U]): TokenMonad[U] =
    new TokenMonad(funcWrapped.get(this.get))
}

object TokenMonad {
  def pure[T](value: T): TokenMonad[T] = new TokenMonad(value)
  def apply[T](value: T): TokenMonad[T] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

/**
 * JSON value ADT for recursive JSON structures.
 * Scala's sealed traits handle recursive types naturally.
 */
sealed trait JsonValue

object JsonValue {
  case object JsonNull extends JsonValue
  final case class JsonString(value: String) extends JsonValue
  final case class JsonNumber(value: BigDecimal) extends JsonValue
  final case class JsonBoolean(value: Boolean) extends JsonValue
  final case class JsonArray(values: Vector[JsonValue]) extends JsonValue
  final case class JsonObject(fields: Map[String, JsonValue]) extends JsonValue

  // Implicit conversions for convenience
  implicit def fromString(s: String): JsonValue = JsonString(s)
  implicit def fromInt(i: Int): JsonValue = JsonNumber(BigDecimal(i))
  implicit def fromDouble(d: Double): JsonValue = JsonNumber(BigDecimal(d))
  implicit def fromBoolean(b: Boolean): JsonValue = JsonBoolean(b)
}

/**
 * Tokenizer for JSON structures with recursive types.
 */
final class JsonTokenizer(pretty: Boolean = false) {

  private def toJsonString(value: JsonValue): String = {
    value match {
      case JsonValue.JsonNull         => "null"
      case JsonValue.JsonString(s)    => s""""${escapeString(s)}""""
      case JsonValue.JsonNumber(n)    => n.toString
      case JsonValue.JsonBoolean(b)   => b.toString
      case JsonValue.JsonArray(arr)   =>
        val elements = arr.map(toJsonString)
        if (pretty) {
          elements.mkString("[\n  ", ",\n  ", "\n]")
        } else {
          elements.mkString("[", ",", "]")
        }
      case JsonValue.JsonObject(obj)  =>
        val fields = obj.map { case (k, v) =>
          s""""${escapeString(k)}":${if (pretty) " " else ""}${toJsonString(v)}"""
        }
        if (pretty) {
          fields.mkString("{\n  ", ",\n  ", "\n}")
        } else {
          fields.mkString("{", ",", "}")
        }
    }
  }

  private def escapeString(s: String): String =
    s.replace("\\", "\\\\")
      .replace("\"", "\\\"")
      .replace("\n", "\\n")
      .replace("\r", "\\r")
      .replace("\t", "\\t")

  def tokenize(value: JsonValue): Token =
    Token(toJsonString(value), TokenType.Structured, Map("json" -> true))

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.")
    var current: Option[JsonValue] = Some(value)

    for (part <- parts if current.isDefined) {
      current = current.flatMap {
        case JsonValue.JsonObject(obj) => obj.get(part)
        case JsonValue.JsonArray(arr) if part.forall(_.isDigit) =>
          val idx = part.toInt
          if (idx >= 0 && idx < arr.size) Some(arr(idx)) else None
        case _ => None
      }
    }

    current.map(tokenize)
  }
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

/**
 * Basic tokenizer that splits text by whitespace.
 * This is a fundamental tokenization operation used in NLP and text processing.
 */
final class WhitespaceTokenizer(
  lowercase: Boolean = false,
  minLength: Int = 0,
  maxLength: Option[Int] = None,
  stripPunctuation: Boolean = false
) {
  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed.dropWhile(punctuation.contains).reverse.dropWhile(punctuation.contains).reverse
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) {
      return None
    }

    maxLength.foreach { max =>
      if (processed.length > max) {
        processed = processed.take(max)
      }
    }

    if (processed.isEmpty) None else Some(processed)
  }

  /**
   * Split text by whitespace and return list of tokens.
   */
  def tokenize(text: String): List[Token] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.String,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }.toList
  }

  /**
   * Split text by whitespace and return list of token strings.
   * Convenience method that returns just the string values.
   */
  def tokenizeToStrings(text: String): List[String] =
    tokenize(text).map(_.value)

  /**
   * Tokenize text and return tokens with character positions.
   */
  def tokenizeWithPositions(text: String): List[(String, Int, Int)] = {
    var currentPos = 0
    val words = text.split("\\s+").filter(_.nonEmpty)

    words.flatMap { word =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length
      currentPos = end

      processToken(word).map(processed => (processed, start, end))
    }.toList
  }

  /** Return the number of tokens in the text. */
  def countTokens(text: String): Int = tokenize(text).size
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/**
 * Fluent builder for creating tokenizers.
 * Using immutable builder pattern with copy for type safety.
 */
final case class TokenizerBuilder[T] private (
  private val normalizers: Vector[String => String] = Vector.empty,
  private val validators: Vector[T => Boolean] = Vector.empty,
  private val metadata: Map[String, Any] = Map.empty
) {

  def withNormalizer(normalizer: String => String): TokenizerBuilder[T] =
    copy(normalizers = normalizers :+ normalizer)

  def withValidator(validator: T => Boolean): TokenizerBuilder[T] =
    copy(validators = validators :+ validator)

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[T] =
    copy(metadata = metadata ++ entries.toMap)

  /** Build the final tokenizer function. */
  def build: T => Either[String, Token] = { value =>
    // Validate
    val validationError = validators.collectFirst {
      case v if !v(value) => s"Validation failed for $value"
    }

    validationError match {
      case Some(error) => Left(error)
      case None =>
        // Convert to string
        var strValue = value.toString

        // Normalize
        for (normalizer <- normalizers) {
          strValue = normalizer(strValue)
        }

        Right(Token(strValue, TokenType.String, metadata))
    }
  }

  /**
   * Build a tokenizer that throws exceptions on validation failure.
   * Provided for compatibility with Python version.
   */
  def buildUnsafe: T => Token = { value =>
    build(value) match {
      case Right(token) => token
      case Left(error)  => throw new IllegalArgumentException(error)
    }
  }
}

object TokenizerBuilder {
  def apply[T](): TokenizerBuilder[T] = new TokenizerBuilder[T]()
}

